using MediatR; using JTradeERP.Application.Common.Persistence;
namespace JTradeERP.Application.Features.Security.Administration.GetUsers;
public sealed record GetUsersQuery(string? Search=null,bool? IsActive=null):IRequest<GetUsersResponse>; public sealed record UserListItemResponse(Guid Id,string UserName,string Email,bool IsActive); public sealed record GetUsersResponse(IReadOnlyCollection<UserListItemResponse> Items);
public sealed class GetUsersHandler(IApplicationDbContext db):IRequestHandler<GetUsersQuery,GetUsersResponse>{public Task<GetUsersResponse> Handle(GetUsersQuery r,CancellationToken ct){var q=db.Users.AsEnumerable();if(!string.IsNullOrWhiteSpace(r.Search))q=q.Where(x=>x.UserName.Contains(r.Search,StringComparison.OrdinalIgnoreCase)||x.Email.Contains(r.Search,StringComparison.OrdinalIgnoreCase));if(r.IsActive.HasValue)q=q.Where(x=>x.IsActive==r.IsActive.Value);return Task.FromResult(new GetUsersResponse(q.OrderBy(x=>x.UserName).Select(x=>new UserListItemResponse(x.Id,x.UserName,x.Email,x.IsActive)).ToArray()));}}
public static class GetUsersEndpoint{public static void Map(IEndpointRouteBuilder e)=>e.MapGet("/users",async(string? search,bool? isActive,ISender s,CancellationToken t)=>Results.Ok(await s.Send(new GetUsersQuery(search,isActive),t))).RequirePermission("Admin.Users.Manage",Capability.Full);}
